p = Page()
p.h2("خرمشهر در سال‌های اخیر؛ پل تازه، ساحل‌هایی که سامان می‌گیرند")
p.p("خرمشهر را با خاطرهٔ جنگ و آزادی‌اش می‌شناسیم، اما من در این بخش خواستم خرمشهر امروز را نشان بدهم: شهری که پروژه‌های بزرگی در آن به نتیجه رسیده و هنوز با کمبودهای روشنی در زیرساخت روبه‌روست.")
p.h3("پل شهدای خرمشهر")
p.p("مهم‌ترین پروژهٔ تازهٔ شهر، پل شهدای خرمشهر است که در شهریور ۱۴۰۵ با حضور استاندار خوزستان به بهره‌برداری رسید. این پل ۷۳۰ متر طول و ۳۰ متر عرض دارد، ۱۵ متر بالاتر از سطح آب ساخته شده و پیاده‌راهی به عرض چهار متر هم دارد؛ هزینهٔ اجرای آن بیش از ۳۰ هزار میلیارد ریال اعلام شد.", BRIDGEK)
p.p("به نظر من پیاده‌راه این پل یکی از بهترین جاها برای دیدن رودخانه در غروب است؛ فقط در تابستان، این پیاده‌روی را به ساعت‌های پس از غروب موکول کنید.")
p.h3("گردشگری رودخانه‌ای؛ اسکله‌های مجاز")
p.p("گردشگری رودخانه‌ای هم منظم‌تر شده است. از ۲۸ اسفند ۱۴۰۳ برای نوروز، شش ایستگاه مجاز گردشگری دریایی در خرمشهر آماده شد: اسکله‌های سیدنی، چاسبی، کوت شیخ، موزهٔ جنگ، کورنیش و جزیرهٔ مینو. به گفتهٔ مسئولان، در نوروز ۱۴۰۳ حدود ۳۸۰ هزار گردشگر از بنادر خوزستان بازدید کرده بودند.", MARINE)
p.p("برای ایمنی هم محدودهٔ تردد شناورها با بویه مشخص شد و قرار شد در هر ایستگاه دست‌کم یک غریق‌نجات مستقر باشد. همچنین ۸۱۵ جلیقهٔ نجات برای گردشگران رودخانهٔ کارون و ۶۰ جلیقه برای گردشگران جزیرهٔ مینو توزیع شد.", MARINE)
p.p("توصیهٔ من این است که قایق‌سواری را فقط از همین اسکله‌های مجاز و با جلیقهٔ نجات انجام دهید؛ جریان آب در کارون و اروند را نباید دست‌کم گرفت.")
p.p("در همان برنامه، بنرهای اطلاع‌رسانی به سه زبان فارسی، انگلیسی و عربی در بنادر خوزستان نصب شد و قرار شد کیسهٔ زباله میان گردشگران توزیع شود. من هم از شما می‌خواهم زباله‌تان را با خودتان برگردانید تا ساحل کارون و اروند تمیز بماند.", MARINE)
p.h3("ساحل‌سازی و جزیرهٔ مینو")
p.p("در بهمن ۱۴۰۴ مدیرعامل سازمان منطقهٔ آزاد اروند از اختصاص ۳۰ همت اعتبار برای طرح‌های عمرانی و زیربنایی آبادان و خرمشهر خبر داد. به گفتهٔ او ۴۰ هزار میلیارد ریال از این اعتبار برای ساحل‌سازی، توسعهٔ گردشگری، ساماندهی اروند صغیر و اروند کبیر، تملک اراضی گردشگری جزیرهٔ مینو و تکمیل شبکهٔ آب و فاضلاب آبادان و خرمشهر در نظر گرفته شده است.", FUND30)
p.p("در همان مراسم، بهسازی معابر مینوشهر با اعتبار ۶ هزار و ۷۰۰ میلیارد ریال و طرح فضای سبز با ۴۳۰ میلیارد ریال هم آغاز شد. این‌ها بیشتر وعده و آغاز کارند تا نتیجهٔ نهایی؛ من ترجیح می‌دهم پیشرفتشان را در سفرهای بعدی با چشم خودم ببینم و بعد درباره‌اش قضاوت کنم.", FUND30)
p.h3("قطار؛ گزینه‌ای راحت‌تر برای سفرهای دور")
p.p("دسترسی ریلی خرمشهر هم بهتر شده است. از مهر ۱۴۰۴ قطار پنج‌ستارهٔ فدک در مسیرهای خرمشهر–مشهد و اهواز–مشهد راه افتاد تا به مسافران خوزستانی و زائران مشهد خدمت بدهد. برای مسافری که از شهرهای دور می‌آید، این یعنی یک گزینهٔ راحت‌تر به جای سفر طولانی جاده‌ای.", FADAK)
p.h3("پیشنهادهای من برای سفر")
p.p("خرمشهر در تابستان بسیار گرم و شرجی است. به نظر من بهترین زمان سفر، پاییز تا اوایل بهار است. در روز از موزه‌ها و مسجد جامع دیدن کنید و عصرها به بلوار ساحلی بروید. اقامتگاه را در محدودهٔ مرکزی شهر یا آبادان در نزدیکی بگیرید تا رفت‌وآمد شبانه کوتاه و امن باشد.")
p.p("خرمشهر را باید با احترام دید؛ شهری که هنوز در حال ساختن دوبارهٔ خودش است و هر پروژهٔ تازه‌اش برای مردمش معنای بیشتری از یک سازهٔ عمرانی دارد.")
add["khorramshahr-281"] = spec(p, 1019, "2026-11-10 23:26:55")

# ------------------------------------------------------------- shirvan 73
ANA = "https://ana.ir/fa/news/1091490"
HOUSING = "https://www.mehrnews.com/news/6570694"
HOUSING2 = "https://www.irib-news.ir/fa/news/5937286"
ALAEDIN = "https://www.alaedin.travel/travelguide/iran/shirvan"

p = Page()
p.h2("شیروان در سال‌های اخیر؛ رشد آرام گردشگری و صنایع دستی")
p.p("شیروان در خبرهای سراسری کمتر دیده می‌شود، اما وقتی خبرهای محلی این چند سال را کنار هم می‌گذارم، شهری را می‌بینم که آرام اما واقعی در حال رشد است، به‌ویژه در گردشگری و صنایع دستی. کمبودهایش را هم در ادامه آورده‌ام.")
p.h3("اقامتگاه‌های بیشتر")
p.p("به گفتهٔ رئیس ادارهٔ میراث فرهنگی، گردشگری و صنایع دستی شیروان در مهر ۱۴۰۵، شمار تأسیسات گردشگری شهرستان، شامل اقامتگاه‌های بوم‌گردی و خانه‌های مسافر، در یک سال از حدود شش تا هفت مورد به حدود ۱۶ مورد رسیده است.", ANA)
p.p("برای مسافر، این یعنی امروز گزینه‌های اقامت در شیروان و روستاهای اطرافش بیشتر از چند سال پیش است. پیشنهاد من این است که برای سفر خانوادگی، اقامتگاه‌های دارای مجوز رسمی را انتخاب کنید.")
p.h3("صنایع دستی؛ از کلاه پشمی تا هشت نشان ملی")
p.p("همین مسئول گفت در یک سال گذشته بیش از ۵۰ فقره تسهیلات به فعالان صنایع دستی پرداخت شده، او همچنین از ثبت هشت نشان ملی برای صنایع دستی شهرستان خبر داد و گفت تلاش کرده‌اند ظرفیت‌هایی را که سال‌ها مغفول مانده بود، به فرصتی برای اقتصاد محلی تبدیل کنند.", ANA)
p.p("احیای کلاه پشمی و اختصاص اعتبار برای مرمت ارگ نادری هم از دیگر برنامه‌های این اداره در همین دوره بوده است. اگر به شیروان رفتید، به نظر من خرید مستقیم از کارگاه‌ها و هنرمندان محلی بهترین سوغاتی است.", ANA)
p.h3("مسکن و توسعهٔ شهر")
p.p("در شهریور ۱۴۰۴ مدیرکل راه و شهرسازی خراسان شمالی از آغاز الحاق ۱۰۰ هکتار زمین به شهر شیروان برای ساخت حدود ۹ هزار واحد مسکونی خبر داد. به گفتهٔ او، در آن زمان حدود هزار و ۳۰۰ واحد مسکونی در مجاورت مرکز فنی‌وحرفه‌ای کوی وحدت در دست ساخت بود؛ اما به گفتهٔ خود او تنها حدود ۳۰۰ واحد موفق به دریافت وام شده بودند و بقیه به دلیل تأخیر بانک در پرداخت تسهیلات معطل مانده بودند.", HOUSING)
p.p("در مهر ۱۴۰۵ هم قرارداد آماده‌سازی سایت ۲۴ هکتاری مسکن ملی شیروان در محدودهٔ تپهٔ خانلق به ارزش ۳۴۰ میلیارد ریال بسته شد؛ سایتی با هزار و ۱۶۱ واحد که میانگین پیشرفت آن به ۲۵ درصد رسیده بود. در طرح این سایت فضای سبز و پارک جنگلی در بخش میانی و یک مدرسهٔ ۱۲ کلاسه پیش‌بینی شده که اسکلت ساختمان مدرسه تکمیل شده است.", HOUSING2)
p.p("به نظر من این عددها واقعیت شیروان را خوب نشان می‌دهند: نیاز به مسکن زیاد است و پروژه‌ها جلو می‌روند، اما کندتر از آنچه مردم انتظار دارند.")
p.h3("کمبودها؛ نه فرودگاه، نه قطار")
p.p("شیروان فرودگاه و ایستگاه قطار ندارد و سفر به آن جاده‌ای است. این شهر در حدود ۶۰ کیلومتری بجنورد، مرکز استان، و روی جادهٔ آسیایی به سمت مشهد قرار دارد.", ALAEDIN)
p.p("جاذبه‌های شیروان هم کم نیستند؛ از امامزاده حمزه‌رضا که در مسیر زائران قرار دارد تا منطقهٔ حفاظت‌شدهٔ گلول با قوچ و میش اوریال و پرندگان کمیاب. در بازار شهر هم می‌توان گلیم، جاجیم، نمد و دستکش و جوراب پشمی خرید.", ALAEDIN)
p.p("پیشنهاد من: اگر با هواپیما می‌آیید، روی فرودگاه بجنورد یا مشهد حساب کنید و باقی مسیر را با اتوبوس یا خودرو بروید. شیروان شهری آرام با آب‌وهوای معتدل کوهستانی است و برای سفری کوتاه و بی‌دغدغه گزینهٔ خوبی است.")
add["shirvan-73"] = spec(p, 966, "2026-11-10 23:20:58")

# ------------------------------------------------------------- kashmar 69
AIR = "https://www.mehrnews.com/news/6622485"
WATERK = "https://www.mehrnews.com/news/6556641"
SOLAR2 = "https://nabzebaazaar.com/fa/news/233774"

p = Page()
p.h2("کاشمر در سال‌های اخیر؛ انرژی پاک و کمبودهای زیرساختی")
p.p("در خبرهای این چند سال کاشمر، یک پیشرفت روشن در انرژی پاک می‌بینم و چند کمبود قدیمی در حمل‌ونقل و فاضلاب. هر دو را این‌جا آورده‌ام تا تصویر واقعی‌تری از شهر داشته باشید.")
p.p("در شهریور ۱۴۰۵ خبر رسید که نیروگاه خورشیدی ۳ مگاواتی کاشمر در زمینی به مساحت ۴.۵ هکتار و با سرمایه‌گذاری حدود یک میلیون دلار آمادهٔ بهره‌برداری است و قرار است در سطح ۲۰ کیلوولت به شبکه وصل شود. این پروژه را گروه توسعهٔ انرژی نفت و گاز لاوان اجرا کرده و دو نیروگاه خورشیدی دیگر با ظرفیت ۴ و ۱۰ مگاوات هم در منطقهٔ کاشمر در دستور کار است.", SOLAR2)
p.p("اما در زیرساخت‌ها، کمبودها روشن است. امام جمعهٔ کاشمر در مهر ۱۴۰۴ گفت فرودگاه موجود تنها قابلیت فرود هواپیماهای سبک را دارد و باید ارتقا یابد یا فرودگاه تازه‌ای ساخته شود؛ او بر لزوم راه‌آهن و تصفیه‌خانهٔ فاضلاب هم تأکید کرد. به گفتهٔ او، بخش خصوصی در حال ایجاد یک شهرک گلخانه‌ای با سرمایه‌گذاری ۵۰ میلیارد تومانی است و استفاده از فاضلاب تصفیه‌شده برای آبیاری گلخانه‌ها می‌تواند به حل کم‌آبی کمک کند.", AIR)
p.p("به نظر من این ایده برای شهری که اقتصادش به کشمش، پسته و زعفران گره خورده و با کم‌آبی روبه‌روست منطقی است؛ اما تا تصفیه‌خانه ساخته نشود، این طرح هم به همان کمبود قدیمی وابسته می‌ماند.")
p.p("مدیرعامل آب و فاضلاب خراسان رضوی در مرداد ۱۴۰۴ از اجرای بیش از ۱۰ پروژهٔ آب و فاضلاب در کاشمر و سه شهرستان همسایه خبر داد؛ از جمله آغاز ساخت یک مخزن دو هزار متر مکعبی در مجموعهٔ بالاولایت و پایین‌ولایت کاشمر. او گفت تا راه‌اندازی تصفیه‌خانه، فاضلاب مسکن ملی کاشمر به‌طور موقت با سپتیک‌تانک دفع می‌شود.", WATERK)
p.p("پیشنهاد من: برای رسیدن به کاشمر روی جاده حساب کنید، نه پرواز مسافری یا قطار. کاشمر شهری آرام و کشاورزی است و با دانستن این کمبودها، می‌توانید سفری بی‌دغدغه‌تر برنامه‌ریزی کنید.")
add["kashmar-69"] = spec(p, 1203, "2026-11-10 23:20:58")

